337	
338	    /**
339	     * Populate the owner's household size: the number of owners sharing this owner's
340	     * {@code householdId} (including the owner itself). An owner with no household is a household
341	     * of one.
342	     *
343	     * @param owner the owner whose household size should be computed and set
344	     */
345	    private void populateHouseholdSize(Owner owner) {
346	        String householdId = owner.getHouseholdId();
347	        if (!StringUtils.hasText(householdId)) {
348	            owner.setHouseholdSize(1);
349	            return;
350	        }
351	        int size = (int) this.clinicService.findAllOwners().stream()
352	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
353	            .count();
354	        owner.setHouseholdSize(size);
355	    }
356	
357	    /**
358	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
359	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
360	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
361	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
362	     * longer any per-city sequence number.
363	     *
364	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
365	     * @return the generated (collision-free) customer code
366	     */
367	    private String generateCustomerCode(Owner owner) {
368	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
369	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
370	        String baseCode = region + "-" + hash8;
371	        return deduplicateCustomerCode(baseCode);
372	    }
373	
374	    /**
375	     * Return a customer code that does not collide with any existing owner's customer code. When the
376	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
377	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
378	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
379	     * persisted, so it never counts as a collision with itself.
380	     *
381	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
382	     * @return the de-duplicated customer code
383	     */
384	    private String deduplicateCustomerCode(String baseCode) {
385	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
386	            .map(Owner::getCustomerCode)
387	            .filter(java.util.Objects::nonNull)
388	            .collect(java.util.stream.Collectors.toSet());
389	        if (!existingCodes.contains(baseCode)) {
390	            return baseCode;
391	        }
392	        int n = 2;
393	        String candidate = baseCode + "-" + n;
394	        while (existingCodes.contains(candidate)) {
395	            n++;
396	            candidate = baseCode + "-" + n;
397	        }
398	        return candidate;
399	    }
400	
401	    /**
402	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
403	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
404	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
405	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
406	     * known region.
407	     *
408	     * @param postcode the owner's postcode, may be {@code null}
409	     * @param city     the owner's city
410	     * @return the derived region code
411	     */
412	    private String deriveRegion(String postcode, String city) {
413	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
414	            int value = Integer.parseInt(postcode);
415	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
416	                int[] range = entry.getValue();
417	                if (value >= range[0] && value <= range[1]) {
418	                    return entry.getKey();
419	                }
420	            }
421	        }
422	        String region = CITY_REGION.get(city);
423	        return region != null ? region : "UNKNOWN";
424	    }
425	
426	    /**
427	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
428	     * bytes of {@code input}.
429	     *
430	     * @param input  the value to digest
431	     * @param length the number of leading hex characters to return
432	     * @return the truncated upper-case hex digest
433	     */
434	    private String shortSha256Hex(String input, int length) {
435	        try {
436	            byte[] digest = MessageDigest.getInstance("SHA-256")
437	                .digest(input.getBytes(StandardCharsets.UTF_8));
438	            StringBuilder sb = new StringBuilder(digest.length * 2);
439	            for (byte b : digest) {
440	                sb.append(String.format("%02x", b));
441	            }
442	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
443	        } catch (java.security.NoSuchAlgorithmException e) {
444	            throw new IllegalStateException("SHA-256 not available", e);
445	        }
446	    }
447	
448	    /**
449	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
450	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
451	     * that is stored, returned and used for every value derived from it.
452	     *
453	     * @param date the effective registration date (supplied or defaulted)
454	     * @return the same date when it is a weekday, otherwise the next Monday
455	     */
456	    private LocalDate rollToBusinessDay(LocalDate date) {
457	        DayOfWeek dayOfWeek = date.getDayOfWeek();
458	        if (dayOfWeek == DayOfWeek.SATURDAY) {
459	            return date.plusDays(2);
460	        }
461	        if (dayOfWeek == DayOfWeek.SUNDAY) {
462	            return date.plusDays(1);
463	        }
464	        return date;
465	    }
466	
467	    /**
468	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
469	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
470	     *
471	     * @param customerCode     the owner's already-assigned customer code
472	     * @param registrationDate the owner's registration date
473	     * @return the generated membership number
474	     */
475	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
476	        String yy = String.format("%02d", registrationDate.getYear() % 100);
477	        return String.format("%s-M%s", customerCode, yy);
478	    }
479	
480	    /**
481	     * Count the existing owners that share the given first name and last name, comparing each
482	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
483	     * yet persisted, so it is not included in the count.
484	     *
485	     * @param firstName the incoming owner's first name
486	     * @param lastName  the incoming owner's last name
487	     * @return the number of existing namesakes
488	     */
489	    private int countNamesakes(String firstName, String lastName) {
490	        String normalizedFirstName = normalizeForComparison(firstName);
491	        String normalizedLastName = normalizeForComparison(lastName);
492	        return (int) this.clinicService.findAllOwners().stream()
493	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
494	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
495	            .count();
496	    }
497	
498	    /**
499	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
500	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
501	     *
502	     * @param city the incoming owner's city
503	     * @return the number of existing owners already in that city
504	     */
505	    private int countOwnersInCity(String city) {
506	        String normalizedCity = normalizeForComparison(city);
507	        return (int) this.clinicService.findAllOwners().stream()
508	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
509	            .count();
510	    }
511	
512	    /**
513	     * Count the existing owners whose registration date equals the given date. The incoming owner is
514	     * not yet persisted, so it is not included in the count.
515	     *
516	     * @param registrationDate the incoming owner's registration date
517	     * @return the number of existing owners already registered on that date
518	     */
519	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
520	        return (int) this.clinicService.findAllOwners().stream()
521	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
522	            .count();
523	    }
524	
525	    /**
526	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
527	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
528	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
529	     * (postcode is required for the match). When several owners match, the one with the lowest id is
530	     * returned so the result is deterministic; {@code null} when there is no soft match.
531	     *
532	     * @param owner the incoming owner (with normalized telephone and last name resolved)
533	     * @return the lowest-id matching existing owner, or {@code null} when none matches
534	     */
535	    private Owner findPossibleDuplicate(Owner owner) {
536	        if (!StringUtils.hasText(owner.getPostcode())) {
537	            return null;
538	        }
539	        String normalizedLastName = normalizeForComparison(owner.getLastName());
540	        String telephone = owner.getTelephone();
541	        return this.clinicService.findAllOwners().stream()
542	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
543	                && owner.getPostcode().equals(existing.getPostcode())
544	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
545	            .min(java.util.Comparator.comparing(Owner::getId))
546	            .orElse(null);
547	    }
548	
549	    /**
550	     * Generate the deterministic household identifier for the given last name and postcode. The value
551	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
552	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
553	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
554	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
555	     *
556	     * @param lastName the owner's last name
557	     * @param postcode the owner's postcode, may be {@code null}
558	     * @return the deterministic household identifier
559	     */
560	    private String generateHouseholdId(String lastName, String postcode) {
561	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
562	        return shortSha256Hex(key, 12);
563	    }
564	
565	    /**
566	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
567	     * single space, upper-case the result and expand common street-type abbreviations token by token
568	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
569	     * to the empty string. The result is the canonical form that is stored, returned and used for every
570	     * address comparison (household duplicate detection and the shared household id).
571	     *
572	     * @param address the raw address, may be {@code null}
573	     * @return the normalized address
574	     */
575	    private String normalizeAddress(String address) {
576	        if (address == null) {
577	            return "";
578	        }
579	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
580	        if (collapsed.isEmpty()) {
581	            return "";
582	        }
583	        String[] tokens = collapsed.split(" ");
584	        StringBuilder sb = new StringBuilder(collapsed.length());
585	        for (int i = 0; i < tokens.length; i++) {
586	            if (i > 0) {
587	                sb.append(' ');
588	            }
589	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
590	        }
591	        return sb.toString();
592	    }
593	
594	    /**
595	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
596	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
597	     *
598	     * @param value the raw value, may be {@code null}
599	     * @return the normalized value
600	     */
601	    private String normalizeForComparison(String value) {
602	        if (value == null) {
603	            return "";
604	        }
605	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
606	    }
607	
608	    /**
609	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
610	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
611	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
612	     * is returned lower-cased.
613	     *
614	     * @param email the raw email from the request payload, may be {@code null}
615	     * @return the lower-cased email, or {@code null} when none was provided
616	     */
617	    private String normalizeEmail(String email) {
618	        if (!StringUtils.hasText(email)) {
619	            return null;
620	        }
621	        if (!EMAIL_PATTERN.matcher(email).matches()) {
622	            throw new InvalidRequestException(List.of("email"));
623	        }
624	        String lowerCased = email.toLowerCase(Locale.ROOT);
625	        // Reject an address whose domain is on the disposable-domain blocklist.
626	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
627	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
628	            throw new InvalidRequestException(List.of("email"));
629	        }
630	        return lowerCased;
631	    }
632	
633	    /**
634	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
635	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
636	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
637	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
638	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
639	     * to 400 Bad Request).
640	     *
641	     * @param city     the owner's city (used to resolve the region)
642	     * @param postcode the raw postcode from the request payload, may be {@code null}
643	     */
644	    private void validatePostcode(String city, String postcode) {
645	        if (!StringUtils.hasText(postcode)) {
646	            return;
647	        }
648	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
649	            throw new InvalidRequestException(List.of("postcode"));
650	        }
651	        String region = CITY_REGION.get(city);
652	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
653	        if (range != null) {
654	            int value = Integer.parseInt(postcode);
655	            if (value < range[0] || value > range[1]) {
656	                throw new InvalidRequestException(List.of("postcode"));
657	            }
658	        }
659	    }
660	
661	    /**
662	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
663	     * already carries a leading '+' keeps its country code; otherwise the default country code
664	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
665	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
666	     * is thrown (mapped to 400 Bad Request).
667	     *
668	     * @param telephone the raw telephone from the request payload
669	     * @return the E.164 string (e.g. {@code +61412345678})
670	     */
671	    private String normalizeTelephone(String telephone) {
672	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
673	        String candidate;
674	        if (cleaned.startsWith("+")) {
675	            candidate = cleaned;
676	        } else {
677	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
678	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
679	        }
680	        if (!E164_PATTERN.matcher(candidate).matches()) {
681	            throw new InvalidRequestException(List.of("telephone"));
682	        }
683	        // For country codes with a known fixed national-number length, reject a candidate whose
684	        // national digits (everything after the '+' and the country code) do not match that length.
685	        String digits = candidate.substring(1);
686	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
687	            String countryCode = entry.getKey();
688	            if (digits.startsWith(countryCode)) {
689	                int nationalLength = digits.length() - countryCode.length();
690	                if (nationalLength != entry.getValue()) {
691	                    throw new InvalidRequestException(List.of("telephone"));
692	                }
693	                break;
694	            }
695	        }
696	        return candidate;
697	    }
698	
699	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
700	    @Transactional
701	    @Override
702	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
703	        Owner owner = this.clinicService.findOwnerById(ownerId);
704	        if (owner == null) {
705	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
706	        }
707	        this.clinicService.deleteOwner(owner);
708	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Override
713	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
714	        Owner owner = this.clinicService.findOwnerById(ownerId);
715	        if (owner == null) {
716	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
717	        }
718	        HttpHeaders headers = new HttpHeaders();
719	        Pet pet = petMapper.toPet(petFieldsDto);
720	        owner.setId(ownerId);
721	        pet.setOwner(owner);
722	        pet.getType().setName(null);
723	        this.clinicService.savePet(pet);
724	        PetDto petDto = petMapper.toPetDto(pet);
725	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
726	            .buildAndExpand(pet.getId()).toUri());
727	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Override
732	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
733	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
734	        if (currentOwner != null) {
735	            Pet currentPet = this.clinicService.findPetById(petId);
736	            if (currentPet != null) {
737	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
738	                currentPet.setName(petFieldsDto.getName());
739	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
740	                this.clinicService.savePet(currentPet);
741	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
742	            }
743	        }
744	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
745	    }
746	
747	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
748	    @Override
749	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
750	        HttpHeaders headers = new HttpHeaders();
751	        Visit visit = visitMapper.toVisit(visitFieldsDto);
752	        Pet pet = new Pet();
753	        pet.setId(petId);
754	        visit.setPet(pet);
755	        this.clinicService.saveVisit(visit);
756	        VisitDto visitDto = visitMapper.toVisitDto(visit);
757	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
758	            .buildAndExpand(visit.getId()).toUri());
759	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
760	    }
761	
762	
763	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
764	    @Override
765	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
766	        Owner owner = this.clinicService.findOwnerById(ownerId);
767	        if (owner != null) {
768	            Pet pet = owner.getPet(petId);
769	            if (pet != null) {
770	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
771	            }
772	        }
773	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
774	    }
775	}
